package org.slavicmyths.hellqa;
import java.util.*;import net.minecraft.core.*;import net.minecraft.gametest.framework.*;import net.minecraft.server.level.*;import net.minecraft.world.*;import net.minecraft.world.entity.*;import net.minecraft.world.entity.ai.attributes.Attributes;import net.minecraft.world.entity.ExperienceOrb;import net.minecraft.world.item.*;import net.minecraft.world.level.*;import net.minecraft.world.phys.*;import net.neoforged.neoforge.gametest.*;import org.slavicmyths.infernalfurnace.*;import org.slavicmyths.nethersmithing.*;import org.slavicmyths.winters.*;
@GameTestHolder("slavicmyths_hellqa") @PrefixGameTestTemplate(false)
public final class HellExtendedQaTests {
 @GameTest(template="empty") public static void furnace64AndXpOnce(GameTestHelper t){var w=t.getLevel();var pos=t.absolutePos(new BlockPos(2,2,2));w.setBlock(pos,InfernalFurnace.BLOCK.get().defaultBlockState(),3);var tile=(InfernalFurnaceTile)w.getBlockEntity(pos);tile.setItem(0,new ItemStack(Items.RAW_IRON,64));tile.setItem(1,new ItemStack(InfernalFurnace.COAL.get(),4));for(int i=0;i<6400;i++)InfernalFurnaceTile.tick(w,pos,w.getBlockState(pos),tile);HellQaTests.check(tile.getItem(0).isEmpty()&&tile.getItem(2).is(Items.IRON_INGOT)&&tile.getItem(2).getCount()==64,"64 input consumption/output mismatch");var p=HellQaTests.player(t);var menu=new InfernalFurnaceMenu(4,p.getInventory(),tile,new net.minecraft.world.inventory.SimpleContainerData(4));int before=w.getEntitiesOfClass(ExperienceOrb.class,p.getBoundingBox().inflate(3)).stream().mapToInt(ExperienceOrb::getValue).sum();var result=menu.slots.get(2).remove(64);menu.slots.get(2).onTake(p,result);int after=w.getEntitiesOfClass(ExperienceOrb.class,p.getBoundingBox().inflate(3)).stream().mapToInt(ExperienceOrb::getValue).sum();HellQaTests.check(after-before>=44,"Native XP was not awarded for64 smelts: "+(after-before));tile.awardUsedRecipesAndPopExperience(p);int repeated=w.getEntitiesOfClass(ExperienceOrb.class,p.getBoundingBox().inflate(3)).stream().mapToInt(ExperienceOrb::getValue).sum();HellQaTests.check(repeated==after,"Duplicate recipe XP");w.removeBlock(pos,false);System.out.println("HELLQA_PASS real64 smelts and result-slot XP="+(after-before)+" claimed once");t.succeed();}
 @GameTest(template="empty") public static void auraWardActiveSlotAndTwoWinters(GameTestHelper t){var w=t.getLevel().getServer().getLevel(Level.NETHER);var p=new ServerPlayer(w.getServer(),w,new com.mojang.authlib.GameProfile(UUID.randomUUID(),"WardFixture"),ClientInformation.createDefault());p.connection=new HellQaTests.Listener(p);p.setGameMode(net.minecraft.world.level.GameType.SURVIVAL);p.moveTo(0,90,0);var ward=new ItemStack(WintersContent.AURA_WARD.get());p.getInventory().add(ward.copy());HellQaTests.check(!WintersContent.ward(p),"Ward active in ordinary inventory");var curios=top.theillusivec4.curios.api.CuriosApi.getCuriosInventory(p).orElseThrow();var necklace=curios.getStacksHandler("necklace").orElseThrow().getStacks();necklace.setStackInSlot(0,ward.copy());HellQaTests.check(WintersContent.ward(p),"Curios necklace ward inactive");var n=WintersEvents.data(p);n.putLong("AuraStart",WintersEvents.now(p)-3000);WintersEvents.aura(p);HellQaTests.check(!n.contains("AuraStart")&&!p.hasEffect(WintersContent.AURA),"Equipped aura ward did not clear existing aura clock");boolean applied=p.addEffect(new net.minecraft.world.effect.MobEffectInstance(WintersContent.AURA,100));HellQaTests.check(!applied&&!p.hasEffect(WintersContent.AURA),"Effect Applicable bypassed ward");necklace.setStackInSlot(0,ItemStack.EMPTY);HellQaTests.check(!WintersContent.ward(p),"Removed ward still active");WintersEvents.aura(p);HellQaTests.check(n.contains("AuraStart"),"Aura timer did not restart after removal");p.getInventory().add(new ItemStack(WintersContent.AMULET.get()));WintersEvents.refresh(p);HellQaTests.check(WintersEvents.present(p),"Original Two Winters stopped working");WintersEvents.aura(p);HellQaTests.check(!n.contains("AuraStart"),"Original Two Winters aura protection broken");System.out.println("HELLQA_PASS actual Curios active necklace/inventory/removal/aura applicability and original Two Winters regression");t.succeed();}
 @GameTest(template="empty") public static void flailAndKnifeStatusBudgets(GameTestHelper t){var p=HellQaTests.player(t);var target=EntityType.COW.create(t.getLevel());target.setNoAi(true);target.setNoGravity(true);target.getAttribute(Attributes.MAX_HEALTH).setBaseValue(200);target.setHealth(200);target.moveTo(p.position().add(0,.5,3));t.getLevel().addFreshEntity(target);var flail=HellQaTests.item("volcanic_heart_flail");p.setItemInHand(InteractionHand.MAIN_HAND,flail);NetherSkills.release(p,flail,"volcanic_heart_flail",18);HellQaTests.check(target.getHealth()==192&&target.getRemainingFireTicks()>=160&&flail.getDamageValue()==4,"Flail pulse raw/fire/wear");target.getAttribute(Attributes.ARMOR).setBaseValue(6);float armor=(float)target.getAttributeValue(Attributes.ARMOR);NetherSkills.knifeHit(p,target,true);HellQaTests.check(target.hasEffect(net.minecraft.world.effect.MobEffects.WEAKNESS)&&target.getAttributeValue(Attributes.ARMOR)==armor-2,"Knife damage/armor debuff missing");NetherSkills.knifeHit(p,target,true);HellQaTests.check(target.getAttributeValue(Attributes.ARMOR)==armor-2,"Knife debuff stacked");target.getPersistentData().putLong("NetherKnifeArmorUntil",0);NetherWeaponEffects.armorDebuff(target,false);HellQaTests.check(target.getAttributeValue(Attributes.ARMOR)==armor,"Knife armor debuff leaked");target.discard();System.out.println("HELLQA_PASS flail actual pulse/fire/wear, knife status/nonstack/removal (knife projectile separate NOT_RUN)");t.succeed();}
}
